/** §22.1–3 simplified for Phase 1: precondition true ⇒ candidate. Kept as
 * the "Need-satisfaction learning alone" baseline — see
 * experiments/substitution.ts, which runs the SAME scenario through both
 * this and candidateActionsWithAccessibility to isolate what accessibility
 * filtering actually changes. */
export function candidateActions(
  actions: readonly ActionDef[],
  worldFlags: ReadonlySet<string>,
): ActionDef[] {
  return actions.filter((a) => a.preconditionHolds(worldFlags));
}

export interface AccessibilityFilterResult {
  readonly candidates: ActionDef[];
  /** Every Action whose precondition held, with its accessibility and
   * whether it passed the threshold/top-K cut — kept for the UI and trace
   * so "why wasn't X a candidate" is always answerable (§30). */
  readonly evaluated: readonly {
    readonly actionKey: CanonicalActionKey;
    readonly accessibility: Rational;
    readonly passedThreshold: boolean;
    readonly selected: boolean;
  }[];
}

/**
 * Full §22 pipeline: precondition AND accessibility(action's own concept)
 * ≥ θ_A, then canonical top-K_A selection among those that pass. Ties at
 * the K_A boundary break by CanonicalActionKey ascending (§6).
 */
export function candidateActionsWithAccessibility(
  actions: readonly ActionDef[],
  worldFlags: ReadonlySet<string>,
  activation: ActivationVector,
  thetaA: Rational,
  kA: number,
): AccessibilityFilterResult {
  const feasible = actions.filter((a) => a.preconditionHolds(worldFlags));
  const withAccessibility = feasible.map((a) => ({
    action: a,
    accessibility: activation.get(asConceptKey(a.actionKey)) ?? Rational.ZERO,
  }));
  const passing = withAccessibility.filter((e) => e.accessibility.gte(thetaA));
  const ranked = [...passing].sort((x, y) => {
    const cmp = y.accessibility.compare(x.accessibility); // descending
    if (cmp !== 0) return cmp;
    return compareCanonical(x.action.actionKey, y.action.actionKey);
  });
  const selected = ranked.slice(0, Math.max(0, kA));
  const selectedKeys = new Set(selected.map((e) => e.action.actionKey));

  const evaluated = withAccessibility.map((e) => ({
    actionKey: e.action.actionKey,
    accessibility: e.accessibility,
    passedThreshold: e.accessibility.gte(thetaA),
    selected: selectedKeys.has(e.action.actionKey),
  }));

  return { candidates: selected.map((e) => e.action), evaluated };
}

export interface NeedContext {
  readonly def: NeedDef;
  readonly urgency: Rational;
}

/**
 * N_a = Σ_n U_n · C_{subject,n} · μ_{subject,n}   (§23 Need term)

 */
export function evaluateAction(
  action: ActionDef,
  needContexts: readonly NeedContext[],
  expectationsForSubject: (needId: NeedId) => NeedExpectation,
  kC: Rational,
): ScoredAction {
  const perNeedContributions = needContexts.map(({ def, urgency }) => {
    const exp = expectationsForSubject(def.needId);
    const c = confidence(exp.tau, kC);
    const contribution = urgency.mul(c).mul(exp.mu);
    return { needId: def.needId, urgency, confidence: c, mu: exp.mu, contribution };
  });

  const needTerm = perNeedContributions.reduce((acc, c) => acc.add(c.contribution), Rational.ZERO);
  const score = needTerm; // Phase 1: Score(a) = N_a only.
  const boundedScore = Rational.boundedResponse(score);

  return {
    actionKey: action.actionKey,
    needTerm,
    score,
    boundedScore,
    perNeedContributions,
  };
}

describe('Brief §28–29 Phase-2 experiment: Substitution (negative result)', () => {
  it("Priya's accessibility is bit-for-bit identical whether or not Glen is available — accessibility never sees world flags", () => {
    const { scenario, initial, actions, glenAction, priyaAction, glenOutcome } = setup();
    const ctx = defaultExperienceContext(true);
    const worldFlagsAvailable = new Set([WORLD_FLAG_GLEN_AVAILABLE, WORLD_FLAG_PRIYA_AVAILABLE]);
    const worldFlagsUnavailable = new Set([WORLD_FLAG_PRIYA_AVAILABLE]);

    const result = runSubstitutionExperiment(
      PERSON_MINA,
      initial,
      actions,
      glenAction,
      priyaAction,
      glenOutcome,
      scenario.cycleParams,
      'sub-seed',
      8,
      ctx,
      worldFlagsAvailable,
      worldFlagsUnavailable,
    );

    expect(result.comparison.accessibilityIdenticalRegardlessOfGlen).toBe(true);
    expect(result.comparison.priyaAccessibilityGlenAvailable.equals(result.comparison.priyaAccessibilityGlenUnavailable)).toBe(true);

    // What DOES change is precondition-based feasibility, not accessibility.
    const availableKeys = result.comparison.glenAvailableCandidates.candidates.map((c) => c.actionKey);
    const unavailableKeys = result.comparison.glenUnavailableCandidates.candidates.map((c) => c.actionKey);
    expect(availableKeys).toContain(ACTION_VISIT_GLEN);
    expect(unavailableKeys).not.toContain(ACTION_VISIT_GLEN);
    expect(unavailableKeys).toContain(priyaAction.actionKey);

    // Priya was never independently visited in this experiment, so any
    // apparent "preference" for her isn't coming from NeedExpectation either
    // — sharpening the negative result.
    expect(result.comparison.priyaHasNeverBeenVisited).toBe(true);
  });

# 26. What the reset specifically retracts as governing assumptions

The following old assumptions must not silently re-enter CharacterLab merely because previous code or briefs used them.

CharacterLab does **not** assume that:

- seven inherited latent personality dimensions are the final constitutional primitives;
- personality is fully immutable;
- Need is necessarily persistent stored state;
- Values are necessarily derived from Need satisfaction;
- a global associative graph is the cognitive backbone;
- Action accessibility and desirability share one mechanism;
- episodic memory is merely an immutable event record plus retrieval score;
- observer social belief concerns only stable latent personality;
- Affect is reducible to regulatory state;
- inhibition is merely net opposing Action score;
- addiction is adequately represented by instantiating a withdrawal Need;
- every meaningful Action is chosen from one universal scored candidate list;
- one choice equation must govern every form of decision;
- belief about capability and actual skill are interchangeable;
- intent implies successful execution;
- internal state is directly visible in communication;
- historical experience and current recollection are the same information;
- the old additive Phase 0→6 sequence remains the active roadmap.

it('preserves separate expectation and acquired availability through correction and reversal',async()=>{
 const a=await run(),b=await run({},habitScenario().map(x=>x.at<=3?{...x,reward:false}:x)),apps=rows(a.outputs,826n),other=rows(b.outputs,826n);expect(f(apps[4],6n)).toEqual(f(other[4],6n));expect(f(apps[4],5n)).not.toEqual(f(other[4],5n));const probabilities=rows(a.outputs,830n).map(d=>items(f(d,4n),'list').find(p=>key(f(rec(p,421n),1n))===key(OPTIONS[0])));expect(probabilities[4]).toBeDefined();expect(probabilities.at(-1)).toBeUndefined();
 const h=rows(a.outputs,837n);expect(f(h[3],3n)).toBe(false);expect(f(h[3],4n)).toEqual(f(h[3],5n));
},180000);
